public function setProperty($name, $value) {
	if($value === null) {
		return;
	}

	$method = "set" . ucfirst($name);

	if(!method_exists($this->obj, $method)) {
		// no such setter method
		return;
	} else {
		return call_user_func(array($this->obj, $method), $value);
	}
}

