public function parseFile($file) {
    if (!file_exists($file)) return false;
    $fh = fopen($file, 'r');
    if (!$fh) return false;
    $ret = $this->parseHandle($fh);
    fclose($fh);
    return $ret;
}

public function parseMultiFile($file) {
    if (!file_exists($file)) return false;
    $ret = array();
    $fh = fopen($file, 'r');
    if (!$fh) return false;
    while (!feof($fh)) {
        $ret[] = $this->parseHandle($fh);
    }
    fclose($fh);
    return $ret;
}

